\"\"\"Minimal, dependency-free client for OpenAI's Responses API.

Only uses the Python standard library ("'``urllib``, ``json``, ``os``,
``dataclasses``).  The module exposes a small, focused surface:

    from openai_client import send_prompt, ResponsesError

    reply = send_prompt("Summarise the Eiffel Tower in one sentence.")
    print(reply["output_text"])

Authentication is read from the ``OPENAI_API_KEY`` environment variable
by default, and the model from ``OPENAI_MODEL`` (defaulting to
``gpt-4o-mini``).  Both can be overridden per call.
"""

from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Iterable, Mapping, Sequence

__all__ = [
    "ResponsesError",
    "OpenAIClient",
    "send_prompt",
    "send_messages",
]

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")
DEFAULT_TIMEOUT = 60.0
_USER_AGENT = "openai_client.py/0.1 (+stdlib)"


class ResponsesError(RuntimeError):
    """Raised when the Responses API returns an error response."""

    def __init__(self, status, code, message, body):
        super().__init__(f"OpenAI API error {status} {code or '"''}: {message}\".rstrip(\": \"))
        self.status = status
        self.code = code
        self.message = message
        self.body = body


@dataclass
class OpenAIClient:
    \"\"\"Reusable client for the Responses API.

    Parameters
    ----------
    api_key:
        Bearer token.  Falls back to "'``OPENAI_API_KEY`` if omitted.
    model:
        Default model used by :meth:`respond` and :meth:`respond_messages`.
        Defaults to ``OPENAI_MODEL`` or ``gpt-4o-mini``.
    base_url:
        API root.  Override to point at a proxy or a mock server.
    timeout:
        Per-request timeout in seconds.
    organization / project:
        Optional ``OpenAI-Organization`` / ``OpenAI-Project`` headers for
        accounts that scope keys to a project.
    """

    api_key: str | None = None
    model: str = field(default_factory=lambda: os.environ.get("OPENAI_MODEL", DEFAULT_MODEL))
    base_url: str = DEFAULT_BASE_URL
    timeout: float = DEFAULT_TIMEOUT
    organization: str | None = None
    project: str | None = None

    def __post_init__(self) -> None:
        if not self.api_key:
            [REDACTED_SECRET] = os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise RuntimeError(
                "OpenAI API key not provided. Pass api_key=... or set the "
                "OPENAI_API_KEY environment variable."
            )
        if not self.base_url:
            raise ValueError("base_url must be a non-empty string")

    # ------------------------------------------------------------------ public

    def respond(self, prompt: str, **overrides: Any) -> dict:
        """Send a single user ``prompt`` and return the parsed JSON response."""
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError("prompt must be a non-empty string")
        return self._post("/responses", self._build_payload(prompt, None, overrides))

    def respond_messages(
        self, messages: Sequence[Mapping[str, Any]], **overrides: Any
    ) -> dict:
        """Send a structured conversation.  ``messages`` is forwarded as ``input``."""
        messages = list(messages)
        if not messages:
            raise ValueError("messages must be a non-empty sequence")
        for m in messages:
            if not isinstance(m, Mapping) or "role" not in m or "content" not in m:
                raise ValueError(
                    "each message must be a mapping with '"'role' and 'content' keys\"
                )
        return self._post(\"/responses\", self._build_payload(None, messages, overrides))

    def respond_text(self, prompt: str, **overrides: Any) -> str:
        \"\"\"Convenience wrapper returning the assistant text only.\"\"\"
        return self.extract_text(self.respond(prompt, **overrides))

    @staticmethod
    def extract_text(response: Mapping[str, Any]) -> str:
        \"\"\"Pull the assistant text out of a Responses API payload.

        Falls back to scanning "'``output[*].content[*].text`` for the
        common case where ``output_text`` is not provided.
        """
        direct = response.get("output_text")
        if isinstance(direct, str) and direct:
            return direct
        parts: list[str] = []
        for item in response.get("output", []) or []:
            for chunk in item.get("content", []) or []:
                text = chunk.get("text")
                if isinstance(text, str):
                    parts.append(text)
        return "".join(parts)

    # ----------------------------------------------------------------- helpers

    def _build_payload(
        self,
        prompt: str | None,
        messages: list | None,
        overrides: Mapping[str, Any],
    ) -> dict:
        payload: dict = {"model": overrides.pop("model", self.model)}
        if prompt is not None:
            payload["input"] = prompt
        else:
            payload["input"] = messages
        for key, value in overrides.items():
            if value is None:
                continue
            payload[key] = value
        return payload

    def _post(self, path: str, payload: Mapping[str, Any]) -> dict:
        url = self.base_url.rstrip("/") + path
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")

        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": _USER_AGENT,
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project

        request = urllib.request.Request(url, data=body, headers=headers, method="POST")

        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as resp:
                raw = resp.read()
        except urllib.error.HTTPError as exc:
            raise self._http_error(exc) from exc
        except urllib.error.URLError as exc:
            raise ResponsesError(0, None, f"network error: {exc.reason}", None) from exc

        try:
            return json.loads(raw.decode("utf-8"))
        except json.JSONDecodeError as exc:
            raise ResponsesError(200, None, f"invalid JSON in response: {exc}", raw) from exc

    @staticmethod
    def _http_error(exc: urllib.error.HTTPError) -> ResponsesError:
        raw = b""
        try:
            raw = exc.read() or b""
        except Exception:
            pass
        try:
            data = json.loads(raw.decode("utf-8")) if raw else {}
        except Exception:
            data = {"raw": raw.decode("utf-8", "replace")}
        err = (data or {}).get("error") or {}
        return ResponsesError(
            status=exc.code,
            code=err.get("code"),
            message=err.get("message") or exc.reason or "unknown error",
            body=data,
        )


# ---------------------------------------------------------------- module-level helpers

def _client_from_args(
    api_key, model, base_url, timeout, organization, project
) -> OpenAIClient:
    return OpenAIClient(
        api_key=[REDACTED_SECRET]
        model=model or os.environ.get("OPENAI_MODEL", DEFAULT_MODEL),
        base_url=base_url or DEFAULT_BASE_URL,
        timeout=timeout if timeout is not None else DEFAULT_TIMEOUT,
        organization=organization,
        project=project,
    )


def send_prompt(
    prompt: str,
    *,
    api_key: str | None = None,
    model: str | None = None,
    base_url: str | None = None,
    timeout: float | None = None,
    organization: str | None = None,
    project: str | None = None,
    **overrides: Any,
) -> dict:
    """One-shot helper for a single private text prompt."""
    client = _client_from_args(api_key, model, base_url, timeout, organization, project)
    return client.respond(prompt, **overrides)


def send_messages(
    messages: Iterable[Mapping[str, Any]],
    *,
    api_key: str | None = None,
    model: str | None = None,
    base_url: str | None = None,
    timeout: float | None = None,
    organization: str | None = None,
    project: str | None = None,
    **overrides: Any,
) -> dict:
    """One-shot helper for a structured private conversation."""
    client = _client_from_args(api_key, model, base_url, timeout, organization, project)
    return client.respond_messages(messages, **overrides)


def _main(argv: list) -> int:
    if len(argv) < 2 or argv[1] in ("-h", "--help"):
        print(
            "usage: python openai_client.py '"'your prompt' [--model MODEL] [--raw]\\n\"
            \"Reads OPENAI_API_KEY (and optionally OPENAI_MODEL) from the environment.\"
        )
        return 0 if len(argv) >= 2 else 2
    prompt = argv[1]
    raw = \"--raw\" in argv[2:]
    model_override = None
    if \"--model\" in argv[2:]:
        i = argv.index(\"--model\")
        model_override = argv[i + 1]
    try:
        response = send_prompt(prompt, model=model_override)
    except ResponsesError as exc:
        print(f\"error: {exc}\", file=sys.stderr)
        return 1
    if raw:
        print(json.dumps(response, ensure_ascii=False, indent=2))
    else:
        print(OpenAIClient.extract_text(response))
    return 0


if __name__ == \"__main__\":  # pragma: no cover
    raise SystemExit(_main(sys.argv))
